import { API_BASE, trackEvent } from './api';
import { buildAuthHeaders } from './authHeaders';
import axios from 'axios';

export type RescueEntitlementStatus =
  | 'ALLOW_PAID'
  | 'ALLOW_FREE_RESCUE'
  | 'ALLOW_FREE_SPLIT'
  | 'ALLOW_FREE'
  | 'SHOW_PAYWALL_RESCUE'
  | 'SHOW_PAYWALL_SPLIT'
  | 'SHOW_PAYWALL'
  | 'REQUIRE_LOGIN';

export interface RescueEntitlementResult {
  status: RescueEntitlementStatus;
  hasSplitAccess: boolean;
  rescueCreditRemaining: boolean;
  splitCreditRemaining: boolean;
  freeCreditRemaining: boolean;
  allowed: boolean;
  source: 'paid' | 'free_credit' | 'none';
}

function getTodayIST(): string {
  const now = new Date();
  const istOffset = 5.5 * 60 * 60 * 1000;
  const istDate = new Date(now.getTime() + istOffset);
  return istDate.toISOString().split('T')[0];
}

export function isPaidOrAdminUser(userObj?: any): boolean {
  try {
    let user = userObj;
    if (!user && typeof window !== 'undefined') {
      const userRaw = localStorage.getItem('user');
      if (userRaw && userRaw !== 'undefined' && userRaw !== 'null') {
        try {
          user = JSON.parse(userRaw);
        } catch {}
      }

      // Fallback: inspect accessToken payload if user JSON object is not yet loaded
      if (!user) {
        try {
          const accessToken = localStorage.getItem('accessToken');
          if (accessToken) {
            const parts = accessToken.split('.');
            if (parts.length === 3) {
              const payload = JSON.parse(atob(parts[1]));
              if (payload.isAdmin === true || payload.role === 'admin' || payload.role === 'ADMIN') {
                return true;
              }
            }
          }
        } catch {}
      }
    }
    if (!user) {
      if (typeof window !== 'undefined') {
        const betaCode = localStorage.getItem('betaCode');
        if (betaCode) return true;
      }
      return false;
    }

    // 1. Admin status checks
    if (
      user.isAdmin === true ||
      user.role === 'ADMIN' ||
      user.role === 'admin' ||
      user.planType === 'admin'
    ) {
      return true;
    }

    // 2. Expiry / temporary split access checks
    const now = Date.now();
    if (user.planExpiry && new Date(user.planExpiry).getTime() > now) {
      return true;
    }
    if (user.splitAccessUntil && new Date(user.splitAccessUntil).getTime() > now) {
      return true;
    }

    // 3. Paid plan types
    if (user.planType) {
      const pt = String(user.planType).toLowerCase();
      if (pt !== 'free' && pt !== 'guest' && pt !== 'none') {
        return true;
      }
    }

    // 4. Beta pass code in storage
    if (typeof window !== 'undefined') {
      const betaCode = localStorage.getItem('betaCode');
      if (betaCode) return true;
    }

    return false;
  } catch {
    return false;
  }
}

export async function checkRescueEntitlement(actionType: 'rescue' | 'split' = 'rescue'): Promise<RescueEntitlementResult> {
  const mapResult = (raw: {
    status: RescueEntitlementStatus;
    hasSplitAccess?: boolean;
    rescueCreditRemaining?: boolean;
    splitCreditRemaining?: boolean;
    freeCreditRemaining?: boolean;
  }): RescueEntitlementResult => {
    const isAllowed =
      raw.status === 'ALLOW_PAID' ||
      raw.status === 'ALLOW_FREE_RESCUE' ||
      raw.status === 'ALLOW_FREE_SPLIT' ||
      raw.status === 'ALLOW_FREE';
    const src: 'paid' | 'free_credit' | 'none' =
      raw.status === 'ALLOW_PAID' ? 'paid' : (isAllowed ? 'free_credit' : 'none');
    return {
      status: raw.status,
      hasSplitAccess: Boolean(raw.hasSplitAccess),
      rescueCreditRemaining: raw.rescueCreditRemaining ?? true,
      splitCreditRemaining: raw.splitCreditRemaining ?? true,
      freeCreditRemaining: raw.freeCreditRemaining ?? true,
      allowed: isAllowed,
      source: src,
    };
  };

  try {
    const userStr = typeof window !== 'undefined' ? localStorage.getItem('user') : null;
    if (!userStr || userStr === 'null' || userStr === 'undefined') {
      return mapResult({ status: 'REQUIRE_LOGIN', hasSplitAccess: false, freeCreditRemaining: true });
    }
    const user = JSON.parse(userStr);

    if (isPaidOrAdminUser(user)) {
      return mapResult({
        status: 'ALLOW_PAID',
        hasSplitAccess: true,
        rescueCreditRemaining: true,
        splitCreditRemaining: true,
        freeCreditRemaining: true,
      });
    }

    const res = await axios.get(`${API_BASE}/auth/rescue-entitlement?userId=${encodeURIComponent(user.id || '')}&action=${actionType}`, {
      headers: buildAuthHeaders(),
      timeout: 5000
    });
    if (res.data?.success && res.data.data) {
      return mapResult(res.data.data);
    }
  } catch {}

  // Fallback: if user is paid or admin, never downgrade to paywall
  if (typeof window !== 'undefined' && isPaidOrAdminUser()) {
    return mapResult({
      status: 'ALLOW_PAID',
      hasSplitAccess: true,
      rescueCreditRemaining: true,
      splitCreditRemaining: true,
      freeCreditRemaining: true,
    });
  }

  // Fallback: check localStorage for free credit used today (IST calendar day)
  const today = getTodayIST();
  const rescueUsedDate = typeof window !== 'undefined' ? localStorage.getItem('trayago_free_rescue_used_on') : null;
  const splitUsedDate = typeof window !== 'undefined' ? localStorage.getItem('trayago_free_split_used_on') : null;

  // Also support legacy ISO timestamp key
  const legacyUsedAt = typeof window !== 'undefined' ? localStorage.getItem('trayago_free_rescue_used_at') : null;
  const legacyRescueUsed = legacyUsedAt && (Date.now() - new Date(legacyUsedAt).getTime() < 24 * 60 * 60 * 1000);

  const rescueCreditRemaining = !(rescueUsedDate === today || legacyRescueUsed);
  const splitCreditRemaining = !(splitUsedDate === today);

  if (actionType === 'rescue') {
    return mapResult({
      status: rescueCreditRemaining ? 'ALLOW_FREE_RESCUE' : 'SHOW_PAYWALL_RESCUE',
      hasSplitAccess: false,
      rescueCreditRemaining,
      splitCreditRemaining,
      freeCreditRemaining: rescueCreditRemaining
    });
  } else {
    return mapResult({
      status: splitCreditRemaining ? 'ALLOW_FREE_SPLIT' : 'SHOW_PAYWALL_SPLIT',
      hasSplitAccess: false,
      rescueCreditRemaining,
      splitCreditRemaining,
      freeCreditRemaining: splitCreditRemaining
    });
  }
}

export async function consumeRescueFreeCredit(actionType: 'rescue' | 'split' = 'rescue'): Promise<boolean> {
  const today = getTodayIST();
  try {
    if (typeof window !== 'undefined') {
      if (actionType === 'split') {
        localStorage.setItem('trayago_free_split_used_on', today);
      } else {
        localStorage.setItem('trayago_free_rescue_used_on', today);
        localStorage.setItem('trayago_free_rescue_used_at', new Date().toISOString());
      }
    }
    const userStr = typeof window !== 'undefined' ? localStorage.getItem('user') : null;
    if (userStr && userStr !== 'null' && userStr !== 'undefined') {
      const user = JSON.parse(userStr);
      await axios.post(`${API_BASE}/auth/rescue-consume-free`, { userId: user.id, action: actionType }, {
        headers: buildAuthHeaders(),
        timeout: 5000
      });
    }
    trackEvent('free_credit_consumed', undefined, { actionType });
    if (actionType === 'split') {
      trackEvent('split_free_used');
    } else {
      trackEvent('rescue_free_used');
    }
    return true;
  } catch {
    trackEvent('free_credit_consumed', undefined, { actionType });
    return true;
  }
}
